const survives = (liveNeighbors: number): boolean =>
  liveNeighbors === 2 || liveNeighbors === 3;

const isBorn = (liveNeighbors: number): boolean => liveNeighbors === 3;

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const living = new Set(liveCells.map(keyOf));

  const liveNeighborCount = (cell: Cell): number =>
    neighborsOf(cell).filter((neighbor) => living.has(keyOf(neighbor))).length;

  const candidates = new Map<string, Cell>();
  for (const cell of liveCells) {
    candidates.set(keyOf(cell), cell);
    for (const neighbor of neighborsOf(cell)) {
      candidates.set(keyOf(neighbor), neighbor);
    }
  }

  return [...candidates].filter(([cellKey, cell]) =>
    living.has(cellKey)
      ? survives(liveNeighborCount(cell))
      : isBorn(liveNeighborCount(cell)),
  ).map(([, cell]) => cell);
}

